const canvas = document.getElementById('pcb-canvas');
        const ctx = canvas.getContext('2d');
        const overlay = document.getElementById('upload-overlay');
        function loadGerber(input) {
            if (input.files && input.files[0]) {
                const reader = new FileReader();
                reader.onload = function (e) {
                    overlay.style.opacity = '0';
                    setTimeout(() => overlay.classList.add('hidden'), 500);
                    renderMockGerber(); // Simulated rendering for UI demo
                };
                reader.readAsText(input.files[0]);
            }
        }
        function renderMockGerber() {
            // Logic: Simulated PCB trace rendering
            canvas.classList.remove('hidden');
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            // Base Board
            ctx.fillStyle = '#2d5a27';
            ctx.fillRect(50, 50, 500, 300);
            // Large Ground Planes (Simulation)
            ctx.fillStyle = '#24481f';
            ctx.fillRect(60, 60, 200, 100);
            // Traces (Logic Pathways)
            ctx.strokeStyle = '#b8860b';
            ctx.lineWidth = 3;
            ctx.lineJoin = 'round';
            ctx.beginPath();
            ctx.moveTo(70, 70);
            ctx.lineTo(200, 70);
            ctx.lineTo(200, 200);
            ctx.lineTo(400, 200);
            ctx.stroke();
            // Parallel Data Bus
            ctx.lineWidth = 1;
            for (let i = 0; i < 8; i++) {
                ctx.beginPath();
                ctx.moveTo(250, 100 + (i * 10));
                ctx.lineTo(450, 100 + (i * 10));
                ctx.stroke();
            }
            // Component Pads (D03 Flashes)
            ctx.fillStyle = '#d4af37';
            const pads = [[70, 70], [400, 200], [450, 100], [450, 110], [450, 120]];
            pads.forEach(p => {
                ctx.beginPath();
                ctx.arc(p[0], p[1], 6, 0, Math.PI * 2);
                ctx.fill();
            });
            // IC Footprint
            ctx.fillRect(300, 80, 40, 60);
            // Silk Screen (Labels)
            ctx.fillStyle = 'rgba(255, 255, 255, 0.9)';
            ctx.font = 'bold 12px JetBrains Mono';
            ctx.fillText('TOOLKIT-GEN v1.2', 65, 330);
            ctx.fillText('MCU_1', 300, 75);
            ctx.fillText('PWR_IN', 60, 180);
            // Mounting Holes
            ctx.fillStyle = '#1a1a1a';
            [[60, 60], [540, 60], [60, 340], [540, 340]].forEach(h => {
                ctx.beginPath();
                ctx.arc(h[0], h[1], 8, 0, Math.PI * 2);
                ctx.fill();
            });
        }
        function toggleLayer(layer, btn) {
            btn.classList.toggle('active');
            // Heuristic rendering toggle logic
            renderMockGerber();
        }
        function toggleXray(btn) {
            btn.classList.toggle('active');
            if (btn.classList.contains('active')) {
                canvas.style.opacity = '0.6';
                canvas.style.filter = 'invert(1) hue-rotate(180deg) brightness(1.2) contrast(1.5)';
            } else {
                canvas.style.opacity = '1';
                canvas.style.filter = 'none';
            }
        }
